INSERT INTO prompts (id, topic_detail_id, difficulty, question_en, question_ko, tip, display_order, is_active) VALUES ('prompt-routine-2401', @detail_routine_weather_ready_id, 'I', 'What do you usually do before you check the weather forecast?', '일기예보를 확인하기 전에 보통 무엇을 하나요?', '날씨에 맞춰 챙기는 물건이나 행동을 순서대로 말해 보세요.', 7001, 1) ON DUPLICATE KEY UPDATE topic_detail_id = VALUES(topic_detail_id), difficulty = VALUES(difficulty), question_en = VALUES(question_en), question_ko = VALUES(question_ko), tip = VALUES(tip), display_order = VALUES(display_order), is_active = VALUES(is_active);
INSERT INTO prompt_hints (id, prompt_id, hint_type, title, display_order, is_active) VALUES ('hint-routine-2401-1', 'prompt-routine-2401', 'STARTER', '첫 문장 스타터', 1, 1) ON DUPLICATE KEY UPDATE prompt_id = VALUES(prompt_id), hint_type = VALUES(hint_type), title = VALUES(title), display_order = VALUES(display_order), is_active = VALUES(is_active);
