INSERT INTO prompt_hints (id, prompt_id, hint_type, title, display_order, is_active) VALUES ('hint-routine-2401-3', 'prompt-routine-2401', 'VOCAB_PHRASE', '활용 표현', 3, 1) ON DUPLICATE KEY UPDATE prompt_id = VALUES(prompt_id), hint_type = VALUES(hint_type), title = VALUES(title), display_order = VALUES(display_order), is_active = VALUES(is_active);
INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-routine-2401-1-item-1', 'hint-routine-2401-1', 'FRAME', 'Before I check the weather forecast, I usually ...', '나는 보통 ...', '바로 다음 행동을 한두 가지 덧붙여서 시작해 보세요.', 'I usually do one or two simple things that match my routine.', 'STARTER_ROUTINE', 1, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-routine-2401-2-item-1', 'hint-routine-2401-2', 'WORD', 'forecast', '예보', '날씨를 먼저 확인하는 습관을 말할 때 좋아요.', 'I check the forecast before I leave home.', 'INTRO_ROUTINE_WEATHER', 1, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-routine-2401-2-item-2', 'hint-routine-2401-2', 'WORD', 'umbrella', '우산', '비 오는 날 챙기는 물건으로 아주 자주 써요.', 'I keep a small umbrella in my bag.', 'INTRO_ROUTINE_WEATHER', 2, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-routine-2401-2-item-3', 'hint-routine-2401-2', 'WORD', 'jacket', '재킷', '쌀쌀할 때 입는 옷을 말할 때 자연스러워요.', 'I wear a light jacket on cool days.', 'INTRO_ROUTINE_WEATHER', 3, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-routine-2401-2-item-4', 'hint-routine-2401-2', 'WORD', 'scarf', '목도리', '추운 날 준비하는 물건을 말할 때 좋아요.', 'A scarf keeps my neck warm in the morning.', 'INTRO_ROUTINE_WEATHER', 4, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-routine-2401-2-item-5', 'hint-routine-2401-2', 'WORD', 'raincoat', '우비', '비가 많이 올 때 입는 옷을 말할 때 좋아요.', 'I wear a raincoat on very wet days.', 'INTRO_ROUTINE_WEATHER', 5, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-routine-2401-2-item-6', 'hint-routine-2401-2', 'WORD', 'boots', '부츠', '젖은 날 신는 신발을 말할 때 유용해요.', 'Boots help me walk through puddles.', 'INTRO_ROUTINE_WEATHER', 6, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-routine-2401-2-item-7', 'hint-routine-2401-2', 'WORD', 'chilly', '쌀쌀한', '날씨 느낌을 간단하게 설명할 때 좋아요.', 'The evening feels chilly today.', 'INTRO_ROUTINE_WEATHER', 7, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-routine-2401-2-item-8', 'hint-routine-2401-2', 'WORD', 'puddle', '물웅덩이', '비 온 뒤 바닥 상태를 말할 때 좋아요.', 'I try not to step in a puddle.', 'INTRO_ROUTINE_WEATHER', 8, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-routine-2401-2-item-9', 'hint-routine-2401-2', 'WORD', 'hoodie', '후드티', '가볍게 걸치는 옷을 말할 때 자연스러워요.', 'A hoodie is easy to wear on windy days.', 'INTRO_ROUTINE_WEATHER', 9, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-routine-2401-2-item-10', 'hint-routine-2401-2', 'WORD', 'weather', '날씨', '전체 상황을 가장 쉽게 말할 수 있는 기본 단어예요.', 'The weather changes quickly in spring.', 'INTRO_ROUTINE_WEATHER', 10, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-routine-2401-3-item-1', 'hint-routine-2401-3', 'PHRASE', 'check the forecast', '일기예보를 확인하다', '집을 나가기 전 행동으로 자주 써요.', 'I check the forecast every morning.', 'INTRO_ROUTINE_WEATHER', 1, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-routine-2401-3-item-2', 'hint-routine-2401-3', 'PHRASE', 'grab an umbrella', '우산을 챙기다', '급하게 준비하는 느낌을 주기에 좋아요.', 'I grab an umbrella before I head out.', 'INTRO_ROUTINE_WEATHER', 2, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-routine-2401-3-item-3', 'hint-routine-2401-3', 'PHRASE', 'put on a jacket', '재킷을 입다', '날씨에 맞춰 옷을 입는 말을 할 때 좋아요.', 'I put on a jacket when the air feels cold.', 'INTRO_ROUTINE_WEATHER', 3, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-routine-2401-3-item-4', 'hint-routine-2401-3', 'PHRASE', 'wear waterproof shoes', '방수 신발을 신다', '비 오는 날 준비를 구체적으로 말할 수 있어요.', 'I wear waterproof shoes on rainy days.', 'INTRO_ROUTINE_WEATHER', 4, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
