INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-routine-2429-2-item-5', 'hint-routine-2429-2', 'WORD', 'receipt', '영수증', '계산 뒤에 받는 것을 말할 때 써요.', 'I keep the receipt in my bag.', 'INTRO_ROUTINE_SHOPPING', 5, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-routine-2429-2-item-6', 'hint-routine-2429-2', 'WORD', 'cart', '카트', '물건이 많을 때 쓰는 도구를 말할 때 좋아요.', 'I use a cart when I buy many things.', 'INTRO_ROUTINE_SHOPPING', 6, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-routine-2429-2-item-7', 'hint-routine-2429-2', 'WORD', 'aisle', '통로', '가게 안에서 움직이는 곳을 말할 때 좋아요.', 'I walk down the drink aisle first.', 'INTRO_ROUTINE_SHOPPING', 7, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-routine-2429-2-item-8', 'hint-routine-2429-2', 'WORD', 'price', '가격', '사는 이유를 설명할 때 자주 써요.', 'I check the price before I decide.', 'INTRO_ROUTINE_SHOPPING', 8, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
