INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-routine-2441-1-item-1', 'hint-routine-2441-1', 'FRAME', 'Before I choose between two kinds of bread, I usually ...', '나는 보통 ...', '바로 다음 행동을 한두 가지 덧붙여서 시작해 보세요.', 'I usually do one or two simple things that match my routine.', 'STARTER_ROUTINE', 1, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-routine-2441-2-item-1', 'hint-routine-2441-2', 'WORD', 'counter', '카운터', '주문하거나 기다리는 곳을 말할 때 좋아요.', 'I stand near the counter and wait.', 'INTRO_ROUTINE_CAFE', 1, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
