INSERT INTO prompts (id, topic_detail_id, difficulty, question_en, question_ko, tip, display_order, is_active) VALUES ('prompt-preference-2521', @detail_preference_bags_and_daily_carry_items_id, 'I', 'What is your favorite bag pocket for carrying a water bottle, and why do you like it?', '물병을 넣기 좋은 가방 수납칸 중에서 가장 좋아하는 것은 무엇이고, 왜 좋아하나요?', '매일 들고 다니는 가방이나 작은 물건을 떠올리고 편한 점을 말해 보세요.', 7096, 1) ON DUPLICATE KEY UPDATE topic_detail_id = VALUES(topic_detail_id), difficulty = VALUES(difficulty), question_en = VALUES(question_en), question_ko = VALUES(question_ko), tip = VALUES(tip), display_order = VALUES(display_order), is_active = VALUES(is_active);
