INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-preference-2521-1-item-1', 'hint-preference-2521-1', 'FRAME', 'My favorite bag pocket for carrying a water bottle is ... because ...', '내가 가장 좋아하는 것은 ...이고, 이유는 ...이다', '좋아하는 대상과 이유를 한 문장으로 먼저 말해 보세요.', 'My favorite one is simple, useful, and easy to enjoy every day.', 'STARTER_PREFERENCE', 1, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
