INSERT INTO prompt_hint_items (id, hint_id, item_type, content, meaning_ko, usage_tip_ko, example_en, expression_family, display_order, is_active) VALUES ('hint-preference-2561-2-item-5', 'hint-preference-2561-2', 'WORD', 'spoon', '숟가락', '음식을 먹는 도구 취향을 말할 때 자연스러워요.', 'A deep spoon is better for soup.', 'INTRO_PREF_KITCHEN', 5, 1) ON DUPLICATE KEY UPDATE hint_id = VALUES(hint_id), item_type = VALUES(item_type), content = VALUES(content), meaning_ko = VALUES(meaning_ko), usage_tip_ko = VALUES(usage_tip_ko), example_en = VALUES(example_en), expression_family = VALUES(expression_family), display_order = VALUES(display_order), is_active = VALUES(is_active);
